{{ post.vorname }}<h2>Offizielle Vereinsadresse</h2>
<h3>{{ site.title }}</h3>
{% set group = attribute( site, 'club-einstellungen' ) %}
{{ group.offizielle_vereinsadresse.adresse_offiziell }}
<p>Telefon: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="tel:+49{{ group.offizielle_vereinsadresse.telefon_url }}">
  +49 {{ group.offizielle_vereinsadresse.telefon_nice }}
 </a>
</p>
<p>Email: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="mailto:{{ group.offizielle_vereinsadresse.email_adresse }}">
  {{ group.offizielle_vereinsadresse.email_adresse }}
 </a>
</p>

<!-- Vereinsheim Query -->
<h3>Vereinsheim</h3>
{% set group = attribute( site, 'club-einstellungen' ) %}
{{ group.vereinsheim.adresse_vereinsheim }}
<p>Telefon: 
 {% set group = attribute( site, 'club-einstellungen' ) %}
 <a href="tel:+49{{ group.vereinsheim.telefon_url }}">
  +49 {{ group.vereinsheim.telefon_nice }}
 </a>
</p>

<!-- Vorstandsposition Query -->
{% set terms = ['jugendleiter', 'mitgliederverwaltung', 'spielausschuss'] %}

{% for term_slug in terms %}
 <h3>{{ term_slug | title }}</h3>
 
 {% set mit_vorstandsposition = mb.get_posts({
  post_type: 'mitglieder',
  tax_query: [
   {
    taxonomy: 'vorstandsposition',
    field: 'slug', 
    terms: term_slug
   }
  ]
 }) %}
 
 {% if mit_vorstandsposition %}
  {% for post in mit_vorstandsposition %}
   <p><strong>{{ post.vorname }} {{ post.nachname }}</strong></p>
   
   {% if post.vorstand_adresse %}
    <p>{{ post.vorstand_adresse }}</p>
   {% endif %}
   
   {% if post.email_vorstand %}
    <p>Email:
     <a href="mailto:{{ post.email_vorstand }}">
      {{ post.email_vorstand }}
     </a>
    </p>
   {% endif %}
   
   {% if post.telefon_vorstand %}
    <p>Telefon: {{ post.telefon_vorstand }}</p>
   {% endif %}
   
   {% if post.mobil_vorstand %}
    <p>Mobil: {{ post.mobil_vorstand }}</p>
   {% endif %}
  {% endfor %}
 {% else %}
  <p>Kein Mitglied gefunden für diese Position.</p>
 {% endif %}
{% endfor %}
